CREATE TABLE sources (id TEXT PRIMARY KEY, name TEXT NOT NULL, base_url TEXT NOT NULL, language TEXT NOT NULL, feed_url TEXT, collection_type TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, last_collected_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE articles (id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), title TEXT NOT NULL, original_url TEXT NOT NULL UNIQUE, author TEXT, published_at TEXT, language TEXT NOT NULL, summary TEXT NOT NULL, estimated_reading_minutes INTEGER, difficulty TEXT, content_type TEXT NOT NULL DEFAULT 'article', image_url TEXT, collected_at TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE tags (id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, category TEXT NOT NULL);
CREATE TABLE article_tags (article_id TEXT NOT NULL REFERENCES articles(id), tag_id TEXT NOT NULL REFERENCES tags(id), PRIMARY KEY(article_id,tag_id));
